    .where(linkPredicate(orgId, issueId, blockerId))
    .get();
  return row ? toDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
